use std::io::{self,BufRead};
use tiny_glade_reconstruction::building_wall_state;
#[path="../../building/wall_decorator_archivist.rs"]mod archivist;
use archivist::*;
fn ids(s:&str)->std::collections::HashSet<u32>{if s=="-"{return Default::default();}s.split(',').map(|i|i.parse().unwrap()).collect()}
fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
fn decorators(p:&[&str])->TrackedDecorators{let items=if p[1]=="-"{Default::default()}else{p[1].split(',').map(|s|{let(k,v)=s.split_once(':').unwrap();(k.parse().unwrap(),ObservedDecoratorInfo(std::array::from_fn(|i|u8::from_str_radix(&v[i*2..i*2+2],16).unwrap())))}).collect()};TrackedDecorators{removed:ids(p[0]),items,added:ids(p[2])}}
fn decode(d:&TrackedDecorators)->String{let mut removed:Vec<_>=d.removed.iter().collect();removed.sort();let mut added:Vec<_>=d.added.iter().collect();added.sort();let mut items:Vec<_>=d.items.iter().collect();items.sort_by_key(|(k,_)|*k);format!(r#"{{"removed":{:?},"items":[{}],"added":{:?}}}"#,removed,items.iter().map(|(k,v)|format!("[{},\"{}\"]",k,hex(&v.0))).collect::<Vec<_>>().join(","),added)}
fn main(){for line in io::stdin().lock().lines(){let line=line.unwrap();let p:Vec<_>=line.split_whitespace().collect();let tag:u8=p[0].parse().unwrap();let address=match tag{0=>DecoratorStorageAddress::Wall(building_wall_state::WallId(9)),1=>DecoratorStorageAddress::ObservedSpecial1,_=>DecoratorStorageAddress::ObservedSpecial2};let missing=p[1]=="1";let source=decorators(&p[2..5]);let current=decorators(&p[5..8]);let mut storage=DecoratorStorage::default();storage.id_to_address.insert(999,DecoratorStorageAddress::ObservedSpecial2);storage.removed_by_address.insert(address,ids(p[8]));
 if !missing{for k in current.items.keys(){storage.id_to_address.insert(*k,address);}match tag{0=>{storage.walls.insert(building_wall_state::WallId(9),current);},1=>storage.special1=Some(current),_=>storage.special2=Some(current)}}
 let mut archive=DecoratorArchivist::<()>{walls:Default::default(),special1:None,special2:None,collision_a:Default::default(),collision_b:Default::default()};match tag{0=>{archive.walls.insert(building_wall_state::WallId(9),source);},1=>archive.special1=Some(source),_=>archive.special2=Some(source)}
 restore_archived_decorators(&mut archive,&mut storage).unwrap();let target=match tag{0=>storage.walls.get(&building_wall_state::WallId(9)).unwrap(),1=>storage.special1.as_ref().unwrap(),_=>storage.special2.as_ref().unwrap()};let mut index:Vec<_>=storage.id_to_address.iter().map(|(i,a)|match a{DecoratorStorageAddress::Wall(w)=>[*i as u64,0,w.0],DecoratorStorageAddress::ObservedSpecial1=>[*i as u64,1,0],DecoratorStorageAddress::ObservedSpecial2=>[*i as u64,2,0]}).collect();index.sort();println!(r#"{{"target":{},"index":{:?},"archive_wall_count":{},"archive_special_present":[{},{}],"saved_removed_count":{}}}"#,decode(target),index,archive.walls.len(),archive.special1.is_some(),archive.special2.is_some(),storage.removed_by_address.get(&address).map_or(0,|s|s.len()));}}
